def sequence(n, memo=None):
    if memo is None:
        memo = {1: 1, 2: 2}
    if n in memo:
        return memo[n]
    prev = sequence(n - 1, memo)
    if n - prev in memo:
        memo[n] = memo[n - prev]
    else:
        memo[n] = sequence(n - prev, memo)
    return memo[n]

